//! Known-answer vectors for every encoding a second implementation (the TypeScript SDK, an
//! auditor's model) must reproduce: Poseidon2, the domain IVs, key derivation, notes,
//! nullifiers, the tree, the sighash map, note encryption and a full proof.
//!
//! Except for the Poseidon2 vector (Plonky3's own), these were generated by this crate and pin
//! its behaviour: a change here is a consensus change and must bump `CIRCUIT_ID` or a domain
//! version. Regenerate with `GHOST_KAT_PRINT=1 cargo test --test kat -- --nocapture`.
//!
//! The proof vector assumes Plonky3 without its `parallel` feature: proof-of-work search is then
//! sequential, so the same seed gives the same proof. (A parallel build finds other, equally
//! valid, witnesses.)

use blockula_ghost::circuit::{prove_with_seed, sighash_fields};
use blockula_ghost::encryption::{MEMO_BYTES, encrypt_note};
use blockula_ghost::field::{Digest, F, digest_to_bytes};
use blockula_ghost::hash::{Domain, permute, uncommitted_leaf};
use blockula_ghost::tree::{DEPTH, empty_roots};
use blockula_ghost::*;
use p3_field::PrimeField32;
use rand::SeedableRng;
use rand::rngs::StdRng;

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn d(x: &Digest) -> String {
    hex(&digest_to_bytes(x))
}

fn h(bytes: &[u8]) -> String {
    hex(blake3::hash(bytes).as_bytes())
}

/// Compares or, with GHOST_KAT_PRINT set, prints.
fn check(name: &str, got: String, expected: &str) {
    if std::env::var_os("GHOST_KAT_PRINT").is_some() {
        println!("(\"{name}\", \"{got}\"),");
    } else {
        assert_eq!(got, expected, "{name}");
    }
}

#[test]
fn poseidon2_matches_plonky3_reference() {
    let input = [
        894848333, 1437655012, 1200606629, 1690012884, 71131202, 1749206695, 1717947831, 120589055,
        19776022, 42382981, 1831865506, 724844064, 171220207, 1299207443, 227047920, 1783754913,
    ]
    .map(F::new);
    let expected = [
        1934285469, 604889435, 133449501, 1026180808, 1830659359, 176667110, 1391183747, 351743874,
        1238264085, 1292768839, 2023573270, 1201586780, 1360691759, 1230682461, 748270449, 651545025,
    ];
    assert_eq!(permute(input).map(|x| x.as_canonical_u32()), expected);
}

#[test]
fn vectors() {
    let v = vectors_list();
    let got = computed();
    assert_eq!(got.len(), v.len(), "vector list out of date");
    for (name, value) in got {
        let expected = v.iter().find(|(n, _)| *n == name).map(|(_, e)| *e).unwrap_or("");
        check(name, value, expected);
    }
}

fn computed() -> Vec<(&'static str, String)> {
    let mut out = Vec::new();
    for (dom, name) in Domain::ALL.iter().zip(["iv/ak", "iv/nk", "iv/owner", "iv/note-commitment-v1", "iv/nullifier"]) {
        assert!(name.ends_with(dom.name()));
        out.push((name, d(&dom.iv())));
    }
    out.push(("uncommitted-leaf", d(&uncommitted_leaf())));
    out.push(("empty-root-32", d(&empty_roots()[DEPTH])));

    let key = SpendingKey::from_seed([1; 32]);
    let fvk = key.full_viewing_key();
    out.push(("sk", d(&key.sk())));
    out.push(("ak", d(&fvk.ak())));
    out.push(("nk", d(&fvk.nk())));
    out.push(("owner", d(&fvk.owner())));
    out.push(("fvk-blake3", h(&fvk.to_bytes())));
    out.push(("ivk-blake3", h(&fvk.incoming().to_bytes())));
    out.push(("ovk", hex(&fvk.outgoing().0)));
    out.push(("address-blake3", h(&key.address().to_bytes())));
    out.push(("address-fingerprint", key.address().fingerprint()));
    out.push(("account-7-seed", hex(&SpendingKey::from_master(&[2; 32], 7).seed())));

    let note = Note { value: 123_456_789, owner: fvk.owner(), rseed: [3; 32] };
    out.push(("note-rcm", d(&note.rcm())));
    let cm = note.commitment();
    out.push(("note-commitment", d(&cm)));
    out.push(("nullifier", d(&nullifier(&fvk.nk(), &cm, 0x1234_5678))));

    let mut frontier = Frontier::new();
    frontier.append(cm).unwrap();
    for i in 0..5u8 {
        frontier.append(blockula_ghost::field::xof_to_digest("kat leaf", &[i])).unwrap();
    }
    out.push(("frontier-root-6", d(&frontier.root())));
    out.push(("sighash-fields", d(&sighash_fields(&[4; 32]))));

    let mut rng = StdRng::seed_from_u64(5);
    let memo = [9u8; MEMO_BYTES];
    let enc = encrypt_note(&note, &key.address(), &memo, Some(&fvk.outgoing()), &mut rng).unwrap();
    out.push(("enc-ciphertext-blake3", h(&enc.enc)));
    out.push(("out-ciphertext-blake3", h(&enc.out)));

    // A full action and proof with fixed masks.
    let mut tree = FullTree::new();
    let pos = tree.append(cm).unwrap();
    let mut rng = StdRng::seed_from_u64(6);
    let w = ActionWitness {
        spends: [SpendWitness::new(&key, note, tree.path(pos).unwrap()), SpendWitness::dummy(&mut rng)],
        outputs: [
            Note { value: 123_456_000, owner: fvk.owner(), rseed: [5; 32] },
            Note { value: 0, owner: fvk.owner(), rseed: [6; 32] },
        ],
        anchor: tree.root(),
        sighash: [7; 32],
    };
    let (public, proof) = prove_with_seed(&w, [8; 32]).unwrap();
    let fields: Vec<u8> = public.to_fields().iter().flat_map(|x| x.as_canonical_u32().to_le_bytes()).collect();
    out.push(("action-public-blake3", h(&fields)));
    out.push(("action-proof-len", proof.len().to_string()));
    out.push(("action-proof-blake3", h(&proof)));
    verify(&public, &proof).unwrap();
    out
}

